#include <memory>
#include <vector>
#include <iostream>

// BAD: manual new/delete (prone to leaks)
void bad_example() {
    int* data = new int[100];
    // ... do stuff ...
    // if an exception is thrown here, delete never runs -> leak
    delete[] data;
}

// GOOD: RAII with std::vector
void good_example() {
    std::vector<int> data(100);  // automatic cleanup
    // ... do stuff ...
    // vector destructor runs automatically
}

// GOOD: unique_ptr for single objects
void unique_ptr_example() {
    auto ptr = std::make_unique<int>(42);
    std::cout << *ptr << '\n';
    // automatically deleted when ptr goes out of scope
}

// Rule of Five example (for rare cases when you need raw resources)
class Buffer {
    int* data_;
    size_t size_;

public:
    explicit Buffer(size_t size)
        : data_(new int[size]), size_(size) {}

    ~Buffer() { delete[] data_; }

    // Copy constructor
    Buffer(const Buffer& other)
        : data_(new int[other.size_]), size_(other.size_) {
        std::copy(other.data_, other.data_ + size_, data_);
    }

    // Copy assignment
    Buffer& operator=(const Buffer& other) {
        if (this != &other) {
            delete[] data_;
            size_ = other.size_;
            data_ = new int[size_];
            std::copy(other.data_, other.data_ + size_, data_);
        }
        return *this;
    }

    // Move constructor
    Buffer(Buffer&& other) noexcept
        : data_(other.data_), size_(other.size_) {
        other.data_ = nullptr;
        other.size_ = 0;
    }

    // Move assignment
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            size_ = other.size_;
            other.data_ = nullptr;
            other.size_ = 0;
        }
        return *this;
    }
};

