#include <vector>
#include <iostream>
#include <algorithm>

int main() {
    // Construction
    std::vector<int> v1;                  // empty
    std::vector<int> v2(10, 5);           // 10 elements, all 5
    std::vector<int> v3 = {1, 2, 3, 4};   // initializer list

    // Adding elements
    std::vector<int> numbers;
    numbers.reserve(1000);  // pre-allocate for performance
    numbers.push_back(10);
    numbers.push_back(20);
    numbers.emplace_back(30);  // in-place construction (preferred)

    // Access
    int first = numbers[0];       // no bounds check
    int second = numbers.at(1);   // bounds check, throws
    int front = numbers.front();  // first element
    int back = numbers.back();    // last element

    // Size and capacity
    std::cout << "Size: " << numbers.size() << '\n';
    std::cout << "Capacity: " << numbers.capacity() << '\n';
    numbers.shrink_to_fit();  // trim capacity to size

    // Iteration
    // Range-based for (C++11+)
    for (int n : numbers) {
        std::cout << n << ' ';
    }

    // Index loop
    for (size_t i = 0; i < numbers.size(); ++i) {
        std::cout << numbers[i] << ' ';
    }

    // Iterator
    for (auto it = numbers.begin(); it != numbers.end(); ++it) {
        std::cout << *it << ' ';
    }

    // Modifying
    numbers.pop_back();      // remove last
    numbers.insert(numbers.begin() + 1, 15);  // insert at position
    numbers.erase(numbers.begin() + 2);        // erase at position
    numbers.clear();         // remove all

    // Algorithms
    std::sort(numbers.begin(), numbers.end());
    auto it = std::find(numbers.begin(), numbers.end(), 20);
    bool all_positive = std::all_of(numbers.begin(), numbers.end(),
                                    [](int x) { return x > 0; });

    // 2D vector
    std::vector<std::vector<int>> matrix(3, std::vector<int>(4, 0));

    return 0;
}

#include <memory>
#include <iostream>

struct Resource {
    Resource() { std::cout << "Resource acquired\n"; }
    ~Resource() { std::cout << "Resource released\n"; }
    void work() { std::cout << "Working...\n"; }
};

// unique_ptr: exclusive ownership
void unique_ptr_example() {
    auto res = std::make_unique<Resource>();
    res->work();

    // Transfer ownership via move
    auto other = std::move(res);
    // res is now nullptr

    // Unique ptr with custom deleter
    auto file = std::unique_ptr<FILE, decltype(&fclose)>(
        fopen("test.txt", "w"), &fclose);
}  // Resource released when other goes out of scope

// shared_ptr: reference-counted shared ownership
void shared_ptr_example() {
    auto sptr1 = std::make_shared<Resource>();
    {
        auto sptr2 = sptr1;  // ref count: 2
        sptr2->work();
        std::cout << "Use count: " << sptr1.use_count() << '\n';  // 2
    }  // ref count: 1
    std::cout << "Use count: " << sptr1.use_count() << '\n';  // 1
}  // ref count: 0, Resource released

// weak_ptr: non-owning observer, breaks circular references
struct Node {
    std::shared_ptr<Node> next;
    std::weak_ptr<Node> prev;  // use weak_ptr to avoid cycle
    ~Node() { std::cout << "Node destroyed\n"; }
};

void weak_ptr_example() {
    auto a = std::make_shared<Node>();
    auto b = std::make_shared<Node>();
    a->next = b;
    b->prev = a;  // weak_ptr doesn't increase ref count

    // Lock weak_ptr to access (returns shared_ptr or null)
    if (auto shared = b->prev.lock()) {
        std::cout << "Prev node exists\n";
    }
}

