#include <iostream>
#include <string>
#include <vector>

// Base class
class Animal {
protected:
    std::string name_;
    int age_;

public:
    // Constructor with member initializer list
    Animal(std::string name, int age)
        : name_(std::move(name)), age_(age) {
        std::cout << "Animal constructed: " << name_ << '\n';
    }

    // Virtual destructor for polymorphic base
    virtual ~Animal() = default;

    // Virtual function
    virtual std::string speak() const {
        return "...";
    }

    // Const member function
    std::string name() const { return name_; }
    int age() const { return age_; }

    // Static member
    static int count() { return instance_count_; }

private:
    static int instance_count_;
};

int Animal::instance_count_ = 0;

// Derived class
class Dog final : public Animal {
public:
    // Inheriting constructor (C++11)
    using Animal::Animal;

    // Override virtual function
    std::string speak() const override {
        return "Woof!";
    }

    void fetch() const {
        std::cout << name_ << " is fetching\n";
    }
};

class Cat final : public Animal {
public:
    Cat(std::string name, int age, bool indoor)
        : Animal(std::move(name), age), indoor_(indoor) {}

    std::string speak() const override {
        return "Meow!";
    }

private:
    bool indoor_ = true;  // default member initializer
};

// Abstract base class (interface)
class Drawable {
public:
    virtual void draw() const = 0;  // pure virtual
    virtual ~Drawable() = default;
};

class Circle final : public Drawable {
public:
    explicit Circle(double radius) : radius_(radius) {}
    void draw() const override {
        std::cout << "Drawing a circle\n";
    }

private:
    double radius_;
};

// Usage
int main() {
    Dog dog("Buddy", 3);
    Cat cat("Whiskers", 5, true);

    // Polymorphism
    Animal* animals[] = {&dog, &cat};
    for (const auto* a : animals) {
        std::cout << a->name() << " says: " << a->speak() << '\n';
    }

    // Dog-specific method (requires static_cast)
    dog.fetch();

    return 0;
}

#include <algorithm>
#include <numeric>
#include <vector>
#include <iostream>
#include <string>

int main() {
    std::vector<int> nums = {5, 3, 1, 4, 2};

    // Sorting
    std::sort(nums.begin(), nums.end());  // [1, 2, 3, 4, 5]
    std::sort(nums.begin(), nums.end(), std::greater<>()); // descending

    // Searching
    auto it = std::find(nums.begin(), nums.end(), 3);
    if (it != nums.end()) {
        std::cout << "Found at index: " << (it - nums.begin()) << '\n';
    }

    // Binary search (on sorted range)
    bool exists = std::binary_search(nums.begin(), nums.end(), 3);

    // Count occurrences
    int count = std::count(nums.begin(), nums.end(), 3);

    // Transform (map)
    std::vector<int> doubled(nums.size());
    std::transform(nums.begin(), nums.end(), doubled.begin(),
                   [](int x) { return x * 2; });

    // Filter with copy_if
    std::vector<int> evens;
    std::copy_if(nums.begin(), nums.end(),
                 std::back_inserter(evens),
                 [](int x) { return x % 2 == 0; });

    // Min/max element
    auto [min_it, max_it] = std::minmax_element(nums.begin(), nums.end());
    std::cout << "Min: " << *min_it << ", Max: " << *max_it << '\n';

    // All/any/none
    bool all_positive = std::all_of(nums.begin(), nums.end(),
                                    [](int x) { return x > 0; });
    bool has_even = std::any_of(nums.begin(), nums.end(),
                                [](int x) { return x % 2 == 0; });

    // Numeric algorithms
    int sum = std::accumulate(nums.begin(), nums.end(), 0);
    int product = std::accumulate(nums.begin(), nums.end(), 1,
                                  std::multiplies<>());

    // For_each
    std::for_each(nums.begin(), nums.end(),
                  [](int x) { std::cout << x << ' '; });

    // Remove-erase idiom
    nums.erase(std::remove(nums.begin(), nums.end(), 3), nums.end());

    // Generate
    std::vector<int> squares(10);
    int n = 0;
    std::generate(squares.begin(), squares.end(), [&n]() { return n++ * n; });

    // C++20 ranges (more readable)
    // #include <ranges>
    // std::ranges::sort(nums);
    // auto even_view = nums | std::views::filter([](int x) { return x % 2 == 0; });

    return 0;
}

#include <iostream>

int main() {
    // Basic pointers
    int value = 42;
    int* ptr = &value;  // ptr holds address of value

    std::cout << "Value: " << value << '\n';
    std::cout << "Address: " << ptr << '\n';
    std::cout << "Dereferenced: " << *ptr << '\n';  // 42

    *ptr = 99;  // modifies value through pointer
    std::cout << "Modified value: " << value << '\n';  // 99

    // nullptr
    int* null_ptr = nullptr;
    if (null_ptr == nullptr) {
        std::cout << "Pointer is null\n";
    }
    // Dereferencing nullptr is undefined behavior!
    // if (null_ptr) { *null_ptr = 5; }  // CRASH

    // Pointers vs References
    int x = 10;
    int* px = &x;   // pointer: can be reassigned, can be null
    int& rx = x;    // reference: cannot be null, cannot be reseated

    px = nullptr;   // OK: pointer can be null
    // rx = nullptr;  // ERROR: reference must always refer to something

    // Pointer arithmetic (on arrays)
    int arr[] = {10, 20, 30, 40};
    int* p = arr;  // pointer to first element

    std::cout << *p << '\n';        // 10
    std::cout << *(p + 1) << '\n';  // 20
    std::cout << p[2] << '\n';      // 30 (array notation works on pointers)

    // Pointer to pointer
    int** pp = &p;
    std::cout << **pp << '\n';  // 10

    // Function pointer
    int (*add)(int, int) = [](int a, int b) { return a + b; };
    std::cout << add(3, 4) << '\n';  // 7

    // Modern C++: prefer smart pointers for ownership
    // auto uptr = std::make_unique<int>(42);
    // int* raw = uptr.get();  // non-owning observation only

    // void*: type-erased pointer (use sparingly)
    void* vp = &x;
    std::cout << *static_cast<int*>(vp) << '\n';  // must cast back

    return 0;
}
